// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock, uint256 deltaTimestamp) public {
        vm.assume(caller != address(0));
        uint256 startBlock = block.number;
        targetBlock = bound(targetBlock, startBlock, startBlock + 500);
        deltaTimestamp = bound(deltaTimestamp, 1, 1000000);

        vm.deal(caller, 20 ether);

        vm.warp(block.timestamp + deltaTimestamp);

        vm.roll(targetBlock);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok);

        bool shouldBeDrained = (block.number % 15 == 0);
        assertTrue( (address(c).balance == 0) == shouldBeDrained );
    }
}
